/**
 * BOBALAB wordmark, "pearl-O" (brief §C8). Fully outlined inline SVG: glyph
 * outlines come from wordmark-geometry.ts (generated by
 * scripts/brand/build-wordmark.py from the pinned OFL fonts), so it never waits
 * for web fonts. BOBA = Fraunces SOFT 100 / wght 680 / opsz 144; LAB = IBM Plex
 * Mono Medium, cap heights matched, spaced optically to the BOBA rhythm with a
 * little extra air (the A→L join is never tighter than any gap inside LAB, so
 * it never reads "BOBAL AB"; verify VIS-02); the O is a matte pearl with one
 * crescent highlight at 10 o'clock (≤ 25% opacity, hidden below 24 px via `small`).
 */
import { WORDMARK } from "./wordmark-geometry";

const [, , VW, VH] = WORDMARK.viewBox;
const P = WORDMARK.pearl;

/** Crescent highlight: a short stroked arc at 10 o'clock inside the pearl. */
function crescentPath(): string {
  const r = P.r * 0.68;
  const a0 = (200 * Math.PI) / 180;
  const a1 = (252 * Math.PI) / 180;
  const x0 = P.cx + r * Math.cos(a0);
  const y0 = P.cy + r * Math.sin(a0);
  const x1 = P.cx + r * Math.cos(a1);
  const y1 = P.cy + r * Math.sin(a1);
  return `M${x0.toFixed(2)} ${y0.toFixed(2)}A${r.toFixed(2)} ${r.toFixed(2)} 0 0 1 ${x1.toFixed(2)} ${y1.toFixed(2)}`;
}
const CRESCENT = crescentPath();

export interface WordmarkProps {
  /** Rendered height in CSS units (width follows the aspect ratio). */
  height?: string | number;
  /** Hide the highlight (use when rendered below 24 px tall). */
  small?: boolean;
  className?: string;
  /** Accessible name; pass "" when the visible text next to it already names the lab. */
  title?: string;
}

export function Wordmark({
  height = "2rem",
  small = false,
  className,
  title = "BOBALAB",
}: WordmarkProps) {
  const cls = ["bl-wordmark", small && "bl-wordmark--small", className].filter(Boolean).join(" ");
  const a11y = title ? { role: "img", "aria-label": title } : { "aria-hidden": true as const };
  return (
    <svg
      className={cls}
      viewBox={`0 0 ${VW} ${VH}`}
      style={{ height, width: "auto", aspectRatio: `${VW} / ${VH}` }}
      xmlns="http://www.w3.org/2000/svg"
      focusable="false"
      {...a11y}
    >
      {title ? <title>{title}</title> : null}
      <g fill="currentColor">
        {WORDMARK.boba.map((d, i) => (
          <path key={`b${i}`} d={d} />
        ))}
        <circle className="bl-wordmark__pearl-o" cx={P.cx} cy={P.cy} r={P.r} />
        {WORDMARK.lab.map((d, i) => (
          <path key={`l${i}`} d={d} />
        ))}
      </g>
      <path
        className="bl-wordmark__hl"
        d={CRESCENT}
        fill="none"
        stroke="#F7F1E8"
        strokeWidth={(P.r * 0.13).toFixed(2)}
        strokeLinecap="round"
      />
    </svg>
  );
}

/** Wordmark plus descriptor lockup ("Berkeley Operations and Behavioral Analytics Lab"). */
export function WordmarkLockup({
  descriptor,
  height = "3rem",
}: {
  descriptor: string;
  height?: string;
}) {
  return (
    <span className="bl-lockup">
      <Wordmark height={height} title="BOBALAB" />
      <span className="bl-lockup__descriptor">{descriptor}</span>
    </span>
  );
}
